@section('footer')<script>const video=document.getElementById('camera'),canvas=document.getElementById('canvas'),image=document.getElementById('image'),capture=document.getElementById('capture'),submit=document.getElementById('submit'),message=document.getElementById('message');navigator.mediaDevices?.getUserMedia({video:{facingMode:'user'}}).then(stream=>video.srcObject=stream).catch(()=>message.textContent={{ Js::from(__('attendance.camera_unavailable')) }});capture.addEventListener('click',()=>{canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);image.value=canvas.toDataURL('image/jpeg',.85);submit.disabled=!image.value;message.textContent={{ Js::from(__('attendance.capture_ready')) }};});</script>@endsection
